   841  #[derive(Copy, Clone, Debug, PartialEq, Eq, Hash)]
   842  pub enum SelfParamKind {
   843      /// self
   844      Owned,
   845      /// &self
   846      Ref,
   847      /// &mut self
   848      MutRef,
