   851  impl ast::SelfParam {
   852      pub fn kind(&self) -> SelfParamKind {
   853          if self.amp_token().is_some() {
   854              if self.mut_token().is_some() { SelfParamKind::MutRef } else { SelfParamKind::Ref }
